                  sec.blocks.map((block, i) => (
                    <p key={i} style={{ fontSize: 12.5, color: "#3A4A52", lineHeight: 2, margin: "0 0 10px", whiteSpace: "pre-line" }}>{block.text}</p>
                  ))
